INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('3cda2cc0-535a-5af6-9ebb-91ec53e25ea0'::uuid, '0fcc1dc6-280b-5bf9-a17c-2cfbb379f27d'::uuid, 'Projet Villa BS. Ain Diab,Casablanca', 'Un extérieur pensé comme une extension naturelle de l’architecture. Pour cette villa, la conception paysagère vise à créer un espace extérieur harmonieux, élégant et fonctionnel, où la végétation, les circulations et les espaces de vie s’intègrent naturellement à l’architecture. La palette végétale, les textures et les volumes ont été soigneusement étudiés pour créer différentes ambiances tout en conservant une lecture claire et cohérente du jardin.', '["https://lechantier.ma/uploads/media/0cb099a12fc8.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/0cb099a12fc8.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '4.3.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('f8a973b9-7e52-539a-9c32-8f54db47040a'::uuid, '0fcc1dc6-280b-5bf9-a17c-2cfbb379f27d'::uuid, 'Projet Villa AF. Anfa,Casablanca', 'Un jardin pensé comme une véritable extension de l’espace de vie. Pour ce projet, nous avons travaillé sur une composition paysagère mêlant végétation méditerranéenne, plantations structurées et espaces de détente, afin de créer un extérieur à la fois esthétique, fonctionnel et agréable au quotidien. L’objectif : valoriser l’architecture de la villa tout en créant une atmosphère naturelle et harmonieuse, avec une attention particulière portée aux volumes végétaux, aux textures, aux couleurs', '[]'::jsonb, NULL, 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '4.3.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('33a6151d-60c1-5ca4-9499-8bef6c276fee'::uuid, 'e4a3bcce-d7fe-5330-84eb-ec6a90b262b3'::uuid, 'Réalisation — HIGH CONCEPT TRAVAUX SERVICES', 'Mediouna casablanca', '["https://lechantier.ma/uploads/media/7042e59c5860.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/7042e59c5860.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
