INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('98a948d7-858b-59d3-b8fe-8a113ed3a726'::uuid, 'c903bd58-088d-589e-a508-91ba4ea41904'::uuid, 'Immeuble AD', 'Chaque réalisation reflète notre exigence, notre précision et notre engagement à offrir des finitions haut de gamme. Merci à nos clients pour leur confiance. 🤝', '["https://lechantier.ma/uploads/media/de9064db7f6c.webp", "https://lechantier.ma/uploads/media/3f7da58389c2.webp", "https://lechantier.ma/uploads/media/f58f6d00a71f.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/de9064db7f6c.webp', 'Mohammedia', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
