INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('287f1712-3203-57f6-9de9-209316ead6df'::uuid, '2b5834d5-a9ec-5928-be90-6349331121dd'::uuid, 'castor ein Sabaa imm R4', 'Projet immobilier — Aïn Sebaâ, Casablanca Réalisation des travaux de gros œuvre d’un immeuble résidentiel à Aïn Sebaâ, Casablanca, comprenant 12 appartements. Un chantier réalisé avec rigueur et professionnalisme, en privilégiant des matériaux de qualité et une exécution soignée pour garantir la solidité, la durabilité et la qualité de construction. De la structure aux différentes étapes du gros œuvre, chaque détail a été suivi avec attention afin de livrer un bâtiment répondant aux exigences du', '["https://lechantier.ma/uploads/media/f990f7413722.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/f990f7413722.webp', 'de livrer un bâtiment répondant aux exigences du', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('4756b1bb-3880-5c83-8903-26207c055579'::uuid, '2b5834d5-a9ec-5928-be90-6349331121dd'::uuid, 'Immeuble R4 al wahda Ain sbaa', 'Description du projet — Immeuble à Aïn Sebaâ Réalisation des travaux de gros œuvre d’un immeuble résidentiel à Aïn Sebaâ, Casablanca, composé de 4 niveaux et de 8 appartements. Le projet a été réalisé avec une attention particulière portée à la qualité des matériaux, à la solidité de la structure et à la précision de l’exécution. Chaque étape du chantier a fait l’objet d’un suivi rigoureux afin de garantir un ouvrage solide, durable et réalisé dans les règles de l’art. Salvador Construction', '[]'::jsonb, NULL, 'de livrer un bâtiment répondant aux exigences du', (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('adcf636e-32b6-51b2-b110-3f3eec7a3d93'::uuid, '43aad52f-91a9-536e-bccf-12e15255202a'::uuid, 'Réalisation — ATLAS CONFORT ET SECURITE', 'Résidence Siyame, magasin N°5, rue Rocroy - Belvédère', '["https://lechantier.ma/uploads/media/3cb6f1e01e22.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/3cb6f1e01e22.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.2.3' LIMIT 1));
