INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('4b76f6aa-ad36-5b6f-9032-118007353bef'::uuid, 'b9a1ffdf-0b2f-5962-9c4a-2879a93d8615'::uuid, 'Installation de Cheminée en Onyx', 'Conception et installation d''un habillage de cheminée en Onyx avec technique de "Bookmatching" (pose en miroir). Le projet inclut l''intégration d''un système de rétroéclairage LED sur mesure pour sublimer la translucidité naturelle de la pierre et créer une ambiance chaleureuse.', '["https://lechantier.ma/uploads/media/a1c16392299b.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/a1c16392299b.webp', 'Kénitra', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('67332013-d6b6-55a8-88e3-d73b1e40d7b5'::uuid, 'b9a1ffdf-0b2f-5962-9c4a-2879a93d8615'::uuid, 'Installation de Structure Métallique', 'Montage et fixation d''une structure en acier (auvent/support) sur une façade industrielle. Le projet a nécessité l''utilisation d''un chariot télescopique (Maniscopic) pour la pose de précision en hauteur et l''intervention de monteurs qualifiés pour l''ancrage structurel.', '["https://lechantier.ma/uploads/media/7ebc92763912.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/7ebc92763912.webp', 'Kénitra', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
