INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('f8e75300-5da4-5880-a658-967e95ea406f'::uuid, '66ed2645-c123-50be-8145-341954280aa5'::uuid, 'تركيب زجاج لي البلكونات بجودة عالية', 'بالكون بجاج كيحوّل الڤيلا لمساحة أنيقة وعصرية، كيدخل الضوء الطبيعي ويحمي من الريح والبرد، وكيخلق مكان مريح للقهوة، الجلسات العائلية أو الاسترخاء. التصميم على القياس، آمن وسهل التنظيف، كيضيف قيمة جمالية وعملية للدار.', '["https://lechantier.ma/uploads/media/833939806a9b.webp", "https://lechantier.ma/uploads/media/2ab1a0af5187.webp", "https://lechantier.ma/uploads/media/4a9554cd648a.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/833939806a9b.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('85bc3ad4-1c5a-54e2-89f2-b082b139d224'::uuid, '66ed2645-c123-50be-8145-341954280aa5'::uuid, 'حمامات بزجاج عصرية', 'ستمتع بفخامة استثنائية كل يوم! حمامات بزجاج عصرية تمنح حمامك الضوء، الرحابة والأناقة، مقاومة للماء وسهلة التنظيف. حول كل استحمام إلى تجربة رفاهية لا تُنسى!', '["https://lechantier.ma/uploads/media/6d1b470b6136.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/6d1b470b6136.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
