INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('3c3c5224-4c70-54b9-8a0f-921121e1172d'::uuid, 'd44a3868-ed5e-5a8f-b1aa-4f42a11b65f5'::uuid, 'Oulfa prestige - Résidence', 'Travaux de menuiserie aluminium réalisés au projet Oulfa Prestige-Résidences. Fourniture et pose de fenêtres, portes coulissantes et châssis fixes en aluminium de haute qualité. Installation soignée, finitions professionnelles, et respect des délais.', '["https://lechantier.ma/uploads/media/4b84fd9ef855.webp", "https://lechantier.ma/uploads/media/19239c0fb238.webp", "https://lechantier.ma/uploads/media/a6ba9f6f7e20.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/4b84fd9ef855.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9fa15da8-c9dd-5b27-92cb-2bcb1b9193d1'::uuid, 'd44a3868-ed5e-5a8f-b1aa-4f42a11b65f5'::uuid, 'appartements économiques à Oulfa', 'Nous avons eu l’honneur de réaliser les travaux d’aluminium pour les appartements économiques à Oulfa, en assurant : • Des fenêtres et portes coulissantes modernes • Une finition de qualité professionnelle • Un travail soigné et durable Avec AWA Aluminium, vous choisissez la fiabilité, l’expérience et le respect des délais.', '["https://lechantier.ma/uploads/media/ac17517dff08.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ac17517dff08.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '3.3.4' LIMIT 1));
